param([int[]]$Scenarios=@(1,3,5,10),[int]$BasePort=18100)
$ErrorActionPreference='Stop'
$repo=Split-Path $PSScriptRoot
$mvn="$env:USERPROFILE\.m2\wrapper\dists\apache-maven-3.9.12-bin\5nmfsn99br87k5d4ajlekdq10k\apache-maven-3.9.12\bin\mvn.cmd"
$ff=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffmpeg.exe|Select-Object -First 1).FullName
$fp=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffprobe.exe|Select-Object -First 1).FullName
$video=Join-Path $env:TEMP 'youtube-unit-qa-videos\v480.mp4';$root=Join-Path $env:TEMP 'youtube-unit-concurrency-final2';New-Item -ItemType Directory -Force $root|Out-Null;$all=@()
foreach($n in $Scenarios){$port=$BasePort+$n;$dir=Join-Path $root "clients-$n";$data=Join-Path $dir data;New-Item -ItemType Directory -Force $data|Out-Null;$env:PORT="$port";$env:TRANSCODER_DATA_DIR=$data;$env:FFMPEG_BIN=$ff;$env:FFPROBE_BIN=$fp;$api=Start-Process $mvn -ArgumentList 'exec:java' -WorkingDirectory $repo -RedirectStandardOutput (Join-Path $dir api.log) -RedirectStandardError (Join-Path $dir api.err) -PassThru;try{$ready=$false;1..50|%{try{if((Invoke-RestMethod "http://127.0.0.1:$port/health").status -eq 'UP' -and (Invoke-RestMethod "http://127.0.0.1:$port/jobs").Count -eq 0){$ready=$true;break}}catch{};Start-Sleep -Milliseconds 300};if(!$ready){throw 'API não iniciou'};$barrier=Join-Path $dir START;$jobs=1..$n|%{Start-Job -ArgumentList $port,$video,$barrier,$_ -ScriptBlock {param($p,$f,$b,$i)while(!(Test-Path $b)){Start-Sleep -Milliseconds 10};$lines=& curl.exe -sS -w "`nHTTP:%{http_code}" -X POST -F "file=@$f;type=video/mp4" -F "origin=cliente-$i" -F 'permission=sintetico' -F 'profiles=360p' "http://127.0.0.1:$p/videos" 2>&1;[pscustomobject]@{i=$i;raw=($lines -join "`n")}}};New-Item $barrier -ItemType File|Out-Null;$res=$jobs|Receive-Job -Wait -AutoRemoveJob;$res|ConvertTo-Json -Depth 4|Set-Content (Join-Path $dir results.json);$ids=@();foreach($r in $res){$m=[regex]::Match($r.raw,'"id":"([^"]+)"');if($m.Success){$ids+=$m.Groups[1].Value}};$term=@();for($k=0;$k-lt 100 -and $term.Count-lt $ids.Count;$k++){Start-Sleep -Milliseconds 300;$term=@($ids|%{Invoke-RestMethod "http://127.0.0.1:$port/jobs/$_"})};$a=($res|? raw -match 'HTTP:202').Count;$b=($res|? raw -match 'HTTP:429').Count;$c=($term|? status -eq COMPLETED).Count;$f=($term|? status -eq FAILED).Count;$row=[pscustomobject]@{clients=$n;http202=$a;http429=$b;jobsCompleted=$c;jobsFailed=$f;result=if(($a+$b)-eq $n -and $f-eq 0 -and $c-eq $a){'PASS'}else{'FAIL'}};$row|ConvertTo-Json|Set-Content (Join-Path $dir summary.json);$all+=$row;Write-Output ($row|ConvertTo-Json -Compress);if($row.result -eq 'FAIL'){throw "Cenário $n falhou"}}finally{if($api -and !$api.HasExited){Stop-Process $api.Id -Force -ErrorAction SilentlyContinue}}};$all|ConvertTo-Json|Set-Content (Join-Path $root summary.json)
